     8→
     9→export default function TablePage() {
    10→  const params = useParams();
    11→  const slug = params.slug as string;
    12→
    13→  const [data, setData] = useState<Array<Record<string, unknown>>>([]);
    14→  const [columns, setColumns] = useState<ColumnsType<Record<string, unknown>>>([]);
    15→  const [loading, setLoading] = useState(true);
    16→  const [totalRows, setTotalRows] = useState(0);
    17→  const [notFoundError, setNotFoundError] = useState(false);
    18→
    19→  useEffect(() => {
    20→    let cancelled = false;
    21→
    22→    async function loadData() {
    23→      setLoading(true);
    24→      setNotFoundError(false);
    25→      try {
    26→        const [tableResponse, metadataResponse] = await Promise.all([
    27→          fetchTableData(slug),
    28→          fetchTableMetadata(slug),
    29→        ]);
    30→
    31→        if (cancelled) return;
    32→
    33→        const apiColumns: ColumnsType<Record<string, unknown>> = metadataResponse.columns.map((col) => ({
    34→          title: col.name,
    35→          dataIndex: col.name,
    36→          key: col.name,
    37→          width: 160,
    38→          ellipsis: true,
    39→        }));
    40→
    41→        const apiData = tableResponse.data.map((row, index) => ({
    42→          ...row,
    43→          id: (row as Record<string, unknown>).id ?? String(index + 1),
    44→        }));
    45→
    46→        setColumns(apiColumns);
    47→        setData(apiData);
    48→        setTotalRows(metadataResponse.total_rows);
    49→      } catch (err: unknown) {
    50→        if (cancelled) return;
    51→        const status = (err as { status?: number })?.status;
    52→        if (status === 404) {
    53→          setNotFoundError(true);
    54→        } else {
    55→          setNotFoundError(true);
    56→        }
    57→      } finally {
    58→        if (!cancelled) setLoading(false);
    59→      }
    60→    }
    61→
    62→    loadData();
    63→    return () => { cancelled = true; };
    64→  }, [slug]);
    65→
    66→  if (notFoundError && !loading) {
    67→    notFound();
    68→  }
    69→
    70→  return (
    71→    <DataTable
    72→      title={slug}
    73→      data={data as Array<{ id: string }>}
    74→      columns={columns as ColumnsType<{ id: string }>}
    75→      loading={loading}
    76→      totalRows={totalRows}
    77→      usingApi={true}
