    21→interface DataTableProps<T extends { id: string }> {
    22→  title: string;
    23→  data: T[];
    24→  columns: ColumnsType<T>;
    25→  loading?: boolean;
    26→  totalRows?: number;
    27→  usingApi?: boolean;
    28→}
    29→
    30→interface ContextMenuState {
    31→  x: number;
    32→  y: number;
    33→  type: SelectionType;
    34→  rowId: string | null;
    35→  columnKey: string | null;
    36→}
    37→
    38→function escapeCSV(value: unknown): string {
    39→  if (value === null || value === undefined) return '';
    40→  const str = String(value);
    41→  if (str.includes(',') || str.includes('"') || str.includes('\n')) {
    42→    return `"${str.replace(/"/g, '""')}"`;
    43→  }
    44→  return str;
    45→}
    46→
    47→const actionBtnStyle: React.CSSProperties = {
    48→  background: 'none',
    49→  border: 'none',
    50→  cursor: 'pointer',
    51→  borderRadius: 6,
    52→  padding: '7px 12px',
    53→  fontSize: 13,
    54→  display: 'flex',
    55→  alignItems: 'center',
    56→  gap: 8,
    57→  width: '100%',
    58→  textAlign: 'left',
    59→  color: 'inherit',
    60→  transition: 'background 0.15s',
    61→};
    62→
    63→export default function DataTable<T extends { id: string }>({
    64→  title,
    65→  data,
    66→  columns,
    67→  loading = false,
    68→  totalRows,
    69→  usingApi,
    70→}: DataTableProps<T>) {
    71→  const [searchText, setSearchText] = useState('');
    72→  const { currentScheme } = useTheme();
    73→  const cardRef = useRef<HTMLDivElement>(null);
    74→
    75→  const [localData, setLocalData] = useState<T[]>(data);
    76→  const [contextMenu, setContextMenu] = useState<ContextMenuState | null>(null);
    77→  const [drawerOpen, setDrawerOpen] = useState(false);
    78→  const [drawerAction, setDrawerAction] = useState<DrawerAction>('edit');
    79→  const [drawerSelection, setDrawerSelection] = useState<{
    80→    type: SelectionType;
    81→    rowId: string | null;
    82→    columnKey: string | null;
    83→  } | null>(null);
    84→  const [hoveredActionBtn, setHoveredActionBtn] = useState<string | null>(null);
    85→
    86→  useEffect(() => {
    87→    setLocalData(data);
    88→  }, [data]);
    89→
    90→  useEffect(() => {
    91→    if (!contextMenu) return;
    92→    const handler = () => setContextMenu(null);
    93→    document.addEventListener('mousedown', handler);
    94→    return () => document.removeEventListener('mousedown', handler);
    95→  }, [contextMenu]);
    96→
    97→  const openDrawer = useCallback(
    98→    (action: DrawerAction) => {
    99→      if (!contextMenu) return;
   100→      setDrawerAction(action);
   101→      setDrawerSelection({
   102→        type: contextMenu.type,
   103→        rowId: contextMenu.rowId,
   104→        columnKey: contextMenu.columnKey,
   105→      });
   106→      setDrawerOpen(true);
   107→      setContextMenu(null);
   108→    },
   109→    [contextMenu],
   110→  );
   111→
   112→  const handleSave = useCallback(
   113→    (values: Record<string, unknown>, isNew: boolean) => {
   114→      if (isNew) {
   115→        const newRow = { id: `local-${Date.now()}`, ...values } as T;
   116→        setLocalData(prev => [newRow, ...prev]);
   117→      } else if (drawerSelection?.rowId) {
   118→        const rowId = drawerSelection.rowId;
   119→        setLocalData(prev =>
   120→          prev.map(row => (row.id === rowId ? ({ ...row, ...values } as T) : row)),
   121→        );
   122→      }
   123→    },
   124→    [drawerSelection],
   125→  );
   126→
   127→  const columnDefs = useMemo<ColumnDef[]>(
   128→    () =>
   129→      columns
   130→        .map(col => {
   131→          const c = col as Record<string, unknown>;
   132→          return {
   133→            key: (c.key as string) || (c.dataIndex as string) || '',
   134→            title: String(c.title ?? ''),
   135→          };
   136→        })
   137→        .filter(c => c.key),
   138→    [columns],
   139→  );
   140→
   141→  const selectedRowData = useMemo<Record<string, unknown> | null>(() => {
   142→    if (!drawerSelection?.rowId) return null;
   143→    return (localData.find(row => row.id === drawerSelection.rowId) as Record<string, unknown>) ?? null;
   144→  }, [localData, drawerSelection]);
   145→
   146→  const augmentedColumns = useMemo<ColumnsType<T>>(() => {
   147→    const rowSelectorCol: ColumnType<T> = {
   148→      key: '_row_selector',
   149→      title: '',
