   162→              rowId: record.id,
   163→              columnKey: null,
   164→            });
   165→          }}
   166→          title="Select row"
   167→          style={{
   168→            background: 'none',
   169→            border: 'none',
   170→            cursor: 'pointer',
   171→            color: 'var(--text-secondary, #94a3b8)',
   172→            padding: '2px 6px',
   173→            borderRadius: 4,
   174→            display: 'flex',
   175→            alignItems: 'center',
   176→            justifyContent: 'center',
   177→          }}
