   181→      ),
   182→    };
   183→
   184→    const dataCols = columns.map(col => {
   185→      const c = col as Record<string, unknown>;
   186→      const colKey = (c.key as string) || (c.dataIndex as string) || '';
   187→      const originalTitle = col.title;
   188→
   189→      return {
   190→        ...col,
   191→        title: (
