   193→            data-testid={`header-col-${colKey}`}
   194→            onMouseDown={e => e.stopPropagation()}
   195→            onClick={(e: React.MouseEvent) => {
   196→              e.stopPropagation();
   197→              setContextMenu({
   198→                x: e.clientX,
   199→                y: e.clientY,
   200→                type: 'column',
   201→                rowId: null,
   202→                columnKey: colKey,
