   227→    return [rowSelectorCol, ...dataCols] as ColumnsType<T>;
   228→  }, [columns]);
   229→
   230→  const formattedTitle = title.charAt(0).toUpperCase() + title.slice(1);
   231→
   232→  const filteredData = useMemo(() => {
   233→    if (!searchText.trim()) return localData;
   234→    const query = searchText.toLowerCase();
   235→    return localData.filter(row =>
   236→      Object.values(row).some(
   237→        val => val !== null && val !== undefined && String(val).toLowerCase().includes(query),
   238→      ),
   239→    );
   240→  }, [localData, searchText]);
   241→
   242→  const handleDownloadCSV = useCallback(() => {
   243→    if (localData.length === 0) return;
   244→    const columnKeys = columns
   245→      .map(col => {
   246→        const c = col as Record<string, unknown>;
   247→        return (c.dataIndex as string) || (c.key as string) || '';
   248→      })
   249→      .filter(Boolean);
   250→    const columnTitles = columns.map(col => String((col as Record<string, unknown>).title ?? ''));
   251→
   252→    const header = columnTitles.map(escapeCSV).join(',');
   253→    const rows = localData.map(row =>
   254→      columnKeys.map(key => escapeCSV((row as Record<string, unknown>)[key])).join(','),
   255→    );
   256→    const csvContent = [header, ...rows].join('\n');
   257→
   258→    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
   259→    const url = URL.createObjectURL(blob);
   260→    const link = document.createElement('a');
   261→    link.href = url;
   262→    link.download = `${title}.csv`;
   263→    link.click();
   264→    URL.revokeObjectURL(url);
   265→  }, [localData, columns, title]);
   266→
   267→  const handleMouseMove = useCallback((e: React.MouseEvent<HTMLDivElement>) => {
   268→    const el = cardRef.current;
   269→    if (!el) return;
   270→    const rect = el.getBoundingClientRect();
   271→    const x = ((e.clientX - rect.left) / rect.width) * 100;
   272→    const y = ((e.clientY - rect.top) / rect.height) * 100;
   273→    el.style.setProperty('--mouse-x', `${x}%`);
   274→    el.style.setProperty('--mouse-y', `${y}%`);
   275→  }, []);
   276→
   277→  const handleMouseLeave = useCallback(() => {
   278→    const el = cardRef.current;
   279→    if (!el) return;
   280→    el.style.setProperty('--mouse-x', '50%');
   281→    el.style.setProperty('--mouse-y', '50%');
   282→  }, []);
   283→
   284→  const totalCount = totalRows ?? localData.length;
   285→  const filteredCount = filteredData.length;
   286→  const isFiltered = searchText.trim().length > 0;
   287→  const localCount = localData.length;
   288→  const hasLocalChanges = localCount !== data.length;
