    24→    let cancelled = false;
    25→
    26→    async function loadData() {
    27→      setLoading(true);
    28→      setNotFoundError(false);
    29→      setUsingMock(false);
    30→      try {
    31→        const [tableResponse, metadataResponse] = await Promise.all([
    32→          fetchTableData(slug),
    33→          fetchTableMetadata(slug),
    34→        ]);
    35→
    36→        if (cancelled) return;
    37→
    38→        const apiColumns: ColumnsType<Record<string, unknown>> = metadataResponse.columns.map((col) => ({
    39→          title: col.name,
    40→          dataIndex: col.name,
    41→          key: col.name,
    42→          width: 160,
    43→          ellipsis: true,
    44→        }));
    45→
    46→        const apiData = tableResponse.data.map((row, index) => ({
    47→          ...row,
    48→          id: (row as Record<string, unknown>).id ?? String(index + 1),
    49→        }));
    50→
    51→        setColumns(apiColumns);
    52→        setData(apiData);
    53→        setTotalRows(metadataResponse.total_rows);
    54→      } catch {
    55→        if (cancelled) return;
    56→
    57→        if (DEV_TABLES.has(slug)) {
    58→          const mockData = getTableData(slug as TableName) as Array<Record<string, unknown>>;
    59→          const mockColumns = getColumns(slug as TableName) as ColumnsType<Record<string, unknown>>;
    60→          setData(mockData);
    61→          setColumns(mockColumns);
    62→          setTotalRows(mockData.length);
    63→          setUsingMock(true);
    64→        } else {
    65→          setNotFoundError(true);
    66→        }
    67→      } finally {
    68→        if (!cancelled) setLoading(false);
    69→      }
    70→    }
    71→
    72→    loadData();
    73→    return () => { cancelled = true; };
    74→  }, [slug]);
