import { NextResponse } from 'next/server';

// Evaluated at request time so the values come from the running server's
// environment, not baked in at build time.
export const dynamic = 'force-dynamic';

function clean(value: string | undefined): string {
  if (!value || value === 'placeholder-client-id') return '';
  return value;
}

export async function GET() {
  const clientId = clean(
    process.env.AZURE_CLIENT_ID || process.env.NEXT_PUBLIC_AZURE_CLIENT_ID,
  );
  const tenantId = clean(
    process.env.AZURE_TENANT_ID || process.env.NEXT_PUBLIC_AZURE_TENANT_ID,
  );

  return NextResponse.json({ clientId, tenantId });
}

'use client';

import { useEffect, useState } from 'react';
import { MsalProvider } from '@azure/msal-react';
import type { PublicClientApplication } from '@azure/msal-browser';
import { getMsalInstance } from '~/lib/auth';

export default function AuthProvider({ children }: { children: React.ReactNode }) {
  const [instance, setInstance] = useState<PublicClientApplication | null>(null);
  const [configMissing, setConfigMissing] = useState(false);

  useEffect(() => {
    fetch('/api/config')
      .then((res) => res.json())
      .then(({ clientId, tenantId }) => {
        if (!clientId || !tenantId) {
          setConfigMissing(true);
          return;
        }
        const msalInstance = getMsalInstance(clientId, tenantId);
        msalInstance
          .initialize()
          .then(() => msalInstance.handleRedirectPromise())
          .then(() => setInstance(msalInstance));
      })
      .catch(() => setConfigMissing(true));
  }, []);

  if (configMissing) {
    // No Azure credentials configured — AuthGuard will handle the dev bypass.
    return <>{children}</>;
  }

  if (!instance) {
    return (
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          height: '100vh',
          background: '#f8fafc',
        }}
      >
        <span style={{ fontSize: 14, color: '#64748b' }}>Loading...</span>
      </div>
    );
  }

  return <MsalProvider instance={instance}>{children}</MsalProvider>;
}

'use client';

import { useEffect, useState } from 'react';
import { useIsAuthenticated, useMsal } from '@azure/msal-react';
import { InteractionStatus } from '@azure/msal-browser';
import { loginRequest, getAccessToken } from '~/lib/auth';
import { AuthContext } from '~/lib/authContext';

function inIframe(): boolean {
  try {
    return typeof window !== 'undefined' && window.self !== window.top;
  } catch {
    return true;
  }
}

function CenteredLoading({ label }: { label: string }) {
  return (
    <div
      style={{
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        height: '100vh',
        background: 'var(--content-bg, #f8fafc)',
        flexDirection: 'column',
        gap: 12,
      }}
    >
      <div
        style={{
          width: 32,
          height: 32,
          border: '3px solid #e2e8f0',
          borderTopColor: '#1677ff',
          borderRadius: '50%',
          animation: 'spin 0.8s linear infinite',
        }}
      />
      <span style={{ fontSize: 14, color: '#64748b' }}>{label}</span>
      <style>{`@keyframes spin { to { transform: rotate(360deg); } }`}</style>
    </div>
  );
}

export default function AuthGuard({ children }: { children: React.ReactNode }) {
  const isAuthenticated = useIsAuthenticated();
  const { instance, accounts, inProgress } = useMsal();
  const [roles, setRoles] = useState<string[]>([]);
  const [rolesLoading, setRolesLoading] = useState(true);
  const [iframeDetected, setIframeDetected] = useState(false);
  // null = still resolving runtime config; true = no Azure config (dev bypass);
  // false = Azure auth is configured and enforced.
  const [devBypass, setDevBypass] = useState<boolean | null>(null);

  const account = accounts[0] ?? null;
  const displayName = account?.name ?? null;
  const username = account?.username ?? null;

  useEffect(() => {
    fetch('/api/config')
      .then((res) => res.json())
      .then(({ clientId, tenantId }) => {
        setDevBypass(!clientId || !tenantId);
      })
      .catch(() => setDevBypass(true));
  }, []);

  useEffect(() => {
    if (devBypass !== false) return;
    if (!isAuthenticated && inProgress === InteractionStatus.None) {
      if (inIframe()) {
        setIframeDetected(true);
      } else {
        instance.loginRedirect(loginRequest);
      }
    }
  }, [devBypass, isAuthenticated, inProgress, instance]);

  useEffect(() => {
    if (devBypass !== false || !isAuthenticated) return;

    (async () => {
      try {
        const token = await getAccessToken();
        const headers: Record<string, string> = { 'Content-Type': 'application/json' };
        if (token) headers['Authorization'] = `Bearer ${token}`;

        const res = await fetch('/api/proxy/v1/user/roles', { headers });
        const data = res.ok ? await res.json() : { roles: [] };
        setRoles(data.roles ?? []);
      } catch {
        setRoles([]);
      } finally {
        setRolesLoading(false);
      }
    })();
  }, [devBypass, isAuthenticated]);

  if (devBypass === null) {
    return <CenteredLoading label="Loading..." />;
  }

  if (devBypass) {
    return (
      <AuthContext.Provider
        value={{
          displayName: 'Dev User',
          username: 'dev@genworth.net',
          roles: ['admin'],
          rolesLoading: false,
        }}
      >
        <div style={{ position: 'relative' }}>
          <div
            style={{
              position: 'fixed',
              bottom: 16,
              right: 16,
              zIndex: 9998,
              background: '#f59e0b',
              color: '#1c1917',
              fontSize: 11,
              fontWeight: 700,
              padding: '4px 10px',
              borderRadius: 20,
              letterSpacing: '0.04em',
              boxShadow: '0 2px 8px rgba(0,0,0,0.18)',
              userSelect: 'none',
            }}
          >
            DEV MODE — Auth bypassed
          </div>
          {children}
        </div>
      </AuthContext.Provider>
    );
  }

  if (!isAuthenticated || inProgress !== InteractionStatus.None) {
    if (iframeDetected) {
      return (
        <div
          style={{
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            height: '100vh',
            background: 'var(--content-bg, #f8fafc)',
            flexDirection: 'column',
            gap: 16,
            textAlign: 'center',
            padding: '0 24px',
          }}
        >
          <svg width="40" height="40" viewBox="0 0 21 21" fill="none" xmlns="http://www.w3.org/2000/svg">
            <rect width="10" height="10" fill="#F25022" />
            <rect x="11" width="10" height="10" fill="#7FBA00" />
            <rect y="11" width="10" height="10" fill="#00A4EF" />
            <rect x="11" y="11" width="10" height="10" fill="#FFB900" />
          </svg>
          <span style={{ fontSize: 16, fontWeight: 600, color: '#1e293b' }}>
            Sign in with Microsoft
          </span>
          <span style={{ fontSize: 13, color: '#64748b', maxWidth: 280 }}>
            Open the app in a new tab to sign in with your Genworth Microsoft account.
          </span>
          <a
            href={typeof window !== 'undefined' ? window.location.href : '/'}
            target="_blank"
            rel="noopener noreferrer"
            style={{
              display: 'inline-block',
              marginTop: 4,
              padding: '8px 20px',
              background: '#1677ff',
              color: '#fff',
              borderRadius: 6,
              fontSize: 14,
              fontWeight: 500,
              textDecoration: 'none',
            }}
          >
            Open in new tab →
          </a>
        </div>
      );
    }

    return (
      <CenteredLoading
        label={inProgress !== InteractionStatus.None ? 'Signing in...' : 'Redirecting to login...'}
      />
    );
  }

  return (
    <AuthContext.Provider value={{ displayName, username, roles, rolesLoading }}>
      {children}
    </AuthContext.Provider>
  );
}

