    56→async function apiMutate<T>(
    57→  path: string,
    58→  method: 'POST' | 'PUT' | 'DELETE',
    59→  body?: unknown
    60→): Promise<T> {
    61→  const token = await getAccessToken();
    62→  const headers: Record<string, string> = {
    63→    'Content-Type': 'application/json',
    64→  };
    65→  if (token) {
    66→    headers['Authorization'] = `Bearer ${token}`;
    67→  }
    68→
    69→  const res = await fetch(`${API_BASE_URL}${path}`, {
    70→    method,
    71→    headers,
    72→    body: body !== undefined ? JSON.stringify(body) : undefined,
    73→  });
    74→
    75→  if (!res.ok) {
    76→    let detail = res.statusText;
    77→    try {
    78→      const errBody = (await res.json()) as { detail?: string };
    79→      if (errBody?.detail) detail = errBody.detail;
    80→    } catch {
    81→      // response had no JSON body; keep statusText
    82→    }
    83→    throw new Error(`API error ${res.status}: ${detail}`);
    84→  }
    85→
    86→  if (res.status === 204) return undefined as T;
    87→  return res.json() as Promise<T>;
    88→}
